CREATE OR REPLACE FUNCTION public.process_laundry_route_inventory_event(task_id_param uuid, action_param text, event_key_param text, actor_id_param uuid DEFAULT NULL::uuid, actor_name_param text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  task_record RECORD;
  line RECORD;
  apartment_record public.laundry_apartment_stock;
  dirty_record public.laundry_dirty_stock;
  level_record public.stock_levels;
  previous_quantity NUMERIC(12, 2);
  new_quantity NUMERIC(12, 2);
  processed_count INTEGER := 0;
  skipped_count INTEGER := 0;
BEGIN
  IF action_param NOT IN ('deliver', 'collect') OR length(trim(COALESCE(event_key_param, ''))) < 8 THEN
    RAISE EXCEPTION 'Invalid route inventory event';
  END IF;

  SELECT t.id, t.propiedad_id, t.sede_id, t.type INTO task_record
  FROM public.tasks t WHERE t.id = task_id_param;
  IF task_record.id IS NULL OR task_record.propiedad_id IS NULL OR task_record.type <> 'limpieza-turistica' THEN
    RAISE EXCEPTION 'Laundry task not found';
  END IF;

  FOR line IN SELECT * FROM public.resolve_laundry_bag_lines(task_id_param) LOOP
    IF line.warehouse_id IS NULL THEN
      RAISE EXCEPTION 'No stock warehouse configured for product %', line.product_id;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.laundry_inventory_events e
      WHERE e.event_key = event_key_param AND e.product_id = line.product_id
    ) THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;

    IF action_param = 'deliver' THEN
      SELECT * INTO level_record FROM public.stock_levels
      WHERE product_id = line.product_id AND warehouse_id = line.warehouse_id FOR UPDATE;
      IF level_record.id IS NULL OR level_record.current_quantity < line.quantity THEN
        RAISE EXCEPTION 'No hay suficiente stock limpio para entregar la bolsa (%).', line.product_id;
      END IF;
      previous_quantity := level_record.current_quantity;
      new_quantity := previous_quantity - line.quantity;
      UPDATE public.stock_levels SET current_quantity = new_quantity, updated_by = actor_id_param
      WHERE id = level_record.id;
      INSERT INTO public.stock_movements (
        product_id, warehouse_id, movement_type, quantity, previous_quantity, new_quantity,
        reason, task_id, property_id, created_by
      ) VALUES (
        line.product_id, line.warehouse_id, 'salida', line.quantity, previous_quantity, new_quantity,
        'Bolsa de lavanderÃ­a entregada', task_id_param, task_record.propiedad_id, actor_id_param
      );
      INSERT INTO public.laundry_apartment_stock (property_id, product_id, current_quantity, updated_by)
      VALUES (task_record.propiedad_id, line.product_id, line.quantity, actor_id_param)
      ON CONFLICT (property_id, product_id) DO UPDATE
      SET current_quantity = laundry_apartment_stock.current_quantity + EXCLUDED.current_quantity,
          updated_by = EXCLUDED.updated_by, updated_at = now();
      INSERT INTO public.laundry_inventory_events (
        event_key, event_type, task_id, property_id, product_id, warehouse_id, quantity,
        from_location, to_location, metadata, created_by
      ) VALUES (event_key_param, 'deliver', task_id_param, task_record.propiedad_id, line.product_id,
        line.warehouse_id, line.quantity, 'building_storage', 'apartment',
        jsonb_build_object('actor_name', actor_name_param), actor_id_param);
    ELSE
      SELECT * INTO apartment_record FROM public.laundry_apartment_stock
      WHERE property_id = task_record.propiedad_id AND product_id = line.product_id FOR UPDATE;
      IF apartment_record.id IS NULL THEN
        -- Safe opening default: the active apartment starts with one bag line.
        INSERT INTO public.laundry_apartment_stock (property_id, product_id, current_quantity, updated_by)
        VALUES (task_record.propiedad_id, line.product_id, line.quantity, actor_id_param)
        RETURNING * INTO apartment_record;
      END IF;
      IF apartment_record.current_quantity < line.quantity THEN
        RAISE EXCEPTION 'No hay suficiente ropa limpia registrada en el apartamento (%).', line.product_id;
      END IF;
      previous_quantity := apartment_record.current_quantity;
      new_quantity := previous_quantity - line.quantity;
      UPDATE public.laundry_apartment_stock SET current_quantity = new_quantity, updated_by = actor_id_param, updated_at = now()
      WHERE id = apartment_record.id;
      INSERT INTO public.laundry_dirty_stock (product_id, warehouse_id, current_quantity, updated_by)
      VALUES (line.product_id, line.warehouse_id, line.quantity, actor_id_param)
      ON CONFLICT (product_id, warehouse_id) DO UPDATE
      SET current_quantity = laundry_dirty_stock.current_quantity + EXCLUDED.current_quantity,
          updated_by = EXCLUDED.updated_by;
      SELECT * INTO dirty_record FROM public.laundry_dirty_stock
      WHERE product_id = line.product_id AND warehouse_id = line.warehouse_id;
      INSERT INTO public.laundry_dirty_movements (
        product_id, warehouse_id, movement_type, quantity, previous_quantity, new_quantity,
        reason, task_id, property_id, created_by
      ) VALUES (
        line.product_id, line.warehouse_id, 'entrada', line.quantity,
        dirty_record.current_quantity - line.quantity, dirty_record.current_quantity,
        'Bolsa recogida de la limpieza', task_id_param, task_record.propiedad_id, actor_id_param
      );
      INSERT INTO public.laundry_inventory_events (
        event_key, event_type, task_id, property_id, product_id, warehouse_id, quantity,
        from_location, to_location, metadata, created_by
      ) VALUES (event_key_param, 'collect', task_id_param, task_record.propiedad_id, line.product_id,
        line.warehouse_id, line.quantity, 'apartment', 'dirty',
        jsonb_build_object('actor_name', actor_name_param), actor_id_param);
    END IF;
    processed_count := processed_count + 1;
  END LOOP;

  RETURN jsonb_build_object('processed', processed_count, 'skipped', skipped_count, 'action', action_param);
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_laundry_batch(warehouse_id_param uuid, lines_param jsonb, reason_param text, user_id_param uuid, event_key_param text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  line RECORD;
  dirty_record public.laundry_dirty_stock;
  level_record public.stock_levels;
  rejected_record public.laundry_rejected_stock;
  accepted NUMERIC(12, 2);
  rejected NUMERIC(12, 2);
  total NUMERIC(12, 2);
  dirty_previous NUMERIC(12, 2);
  processed_count INTEGER := 0;
  skipped_count INTEGER := 0;
BEGIN
  IF auth.uid() IS NULL OR user_id_param <> auth.uid() THEN
    RAISE EXCEPTION 'The acting user must match the authenticated user';
  END IF;
  IF NOT (public.has_role(auth.uid(), 'admin'::public.app_role)
    OR public.has_role(auth.uid(), 'manager'::public.app_role)
    OR public.has_role(auth.uid(), 'logistics'::public.app_role)) THEN
    RAISE EXCEPTION 'User not allowed to receive laundry';
  END IF;
  IF warehouse_id_param IS NULL OR jsonb_typeof(lines_param) <> 'array'
    OR length(trim(COALESCE(reason_param, ''))) = 0
    OR length(trim(COALESCE(event_key_param, ''))) < 8 THEN
    RAISE EXCEPTION 'Invalid laundry receipt';
  END IF;

  FOR line IN SELECT * FROM jsonb_to_recordset(lines_param) AS x(
    product_id UUID, accepted_quantity NUMERIC, rejected_quantity NUMERIC, rejection_reason TEXT
  ) LOOP
    accepted := COALESCE(line.accepted_quantity, 0);
    rejected := COALESCE(line.rejected_quantity, 0);
    total := accepted + rejected;
    IF line.product_id IS NULL OR accepted < 0 OR rejected < 0 OR total <= 0 THEN
      RAISE EXCEPTION 'Invalid quantity in laundry receipt';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.laundry_inventory_events e
      WHERE e.event_key = event_key_param AND e.product_id = line.product_id
    ) THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;

    SELECT * INTO dirty_record FROM public.laundry_dirty_stock
    WHERE product_id = line.product_id AND warehouse_id = warehouse_id_param FOR UPDATE;
    IF dirty_record.id IS NULL OR dirty_record.current_quantity < total THEN
      RAISE EXCEPTION 'La recepciÃ³n supera la ropa sucia pendiente para %', line.product_id;
    END IF;
    dirty_previous := dirty_record.current_quantity;
    UPDATE public.laundry_dirty_stock
    SET current_quantity = current_quantity - total, updated_by = user_id_param
    WHERE id = dirty_record.id;
    INSERT INTO public.laundry_dirty_movements (
      product_id, warehouse_id, movement_type, quantity, previous_quantity, new_quantity,
      reason, created_by
    ) VALUES (
      line.product_id, warehouse_id_param, 'salida', total, dirty_previous,
      dirty_previous - total, trim(reason_param), user_id_param
    );

    IF accepted > 0 THEN
      INSERT INTO public.stock_levels (product_id, warehouse_id, current_quantity, updated_by)
      VALUES (line.product_id, warehouse_id_param, accepted, user_id_param)
      ON CONFLICT (product_id, warehouse_id) DO UPDATE
      SET current_quantity = stock_levels.current_quantity + EXCLUDED.current_quantity,
          updated_by = EXCLUDED.updated_by;
      SELECT * INTO level_record FROM public.stock_levels
      WHERE product_id = line.product_id AND warehouse_id = warehouse_id_param;
      INSERT INTO public.stock_movements (
        product_id, warehouse_id, movement_type, quantity, previous_quantity, new_quantity,
        reason, created_by
      ) VALUES (
        line.product_id, warehouse_id_param, 'entrada', accepted,
        level_record.current_quantity - accepted, level_record.current_quantity,
        trim(reason_param), user_id_param
      );
    END IF;

    IF rejected > 0 THEN
      SELECT * INTO rejected_record FROM public.laundry_rejected_stock
      WHERE property_id IS NULL AND product_id = line.product_id AND warehouse_id = warehouse_id_param
      FOR UPDATE;
      IF rejected_record.id IS NULL THEN
        INSERT INTO public.laundry_rejected_stock (
          property_id, product_id, warehouse_id, current_quantity, reason, updated_by
        ) VALUES (NULL, line.product_id, warehouse_id_param, rejected,
          COALESCE(NULLIF(trim(line.rejection_reason), ''), trim(reason_param)), user_id_param);
      ELSE
        UPDATE public.laundry_rejected_stock
        SET current_quantity = current_quantity + rejected,
            reason = COALESCE(NULLIF(trim(line.rejection_reason), ''), reason),
            updated_by = user_id_param, updated_at = now()
        WHERE id = rejected_record.id;
      END IF;
    END IF;

    INSERT INTO public.laundry_inventory_events (
      event_key, event_type, property_id, product_id, warehouse_id, quantity,
      from_location, to_location, metadata, created_by
    ) VALUES (
      event_key_param, 'receive', NULL, line.product_id, warehouse_id_param, total,
      'dirty', CASE WHEN rejected > 0 AND accepted > 0 THEN 'storage_and_rejected'
        WHEN rejected > 0 THEN 'rejected' ELSE 'building_storage' END,
      jsonb_build_object('accepted', accepted, 'rejected', rejected), user_id_param
    );
    processed_count := processed_count + 1;
  END LOOP;
  RETURN jsonb_build_object('processed', processed_count, 'skipped', skipped_count);
END;
$function$
